function mat(color,extra={}){return new T.MeshStandardMaterial({color,roughness:.8,...extra})}
function addMesh(geometry,material,parent=worldGroup){const m=new T.Mesh(geometry,material);parent.add(m);return m}
function rod(a,b,r,color,parent=worldGroup){let delta=new T.Vector3().subVectors(b,a),m=addMesh(new T.CylinderGeometry(r*.6,r,delta.length(),6),mat(color),parent);m.position.copy(a).add(b).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());return m}
function disposeGroup(group){if(!group)return;const geometries=new Set(),materials=new Set(),textures=new Set();group.traverse(obj=>{if(obj.geometry)geometries.add(obj.geometry);if(obj.material)for(const m of Array.isArray(obj.material)?obj.material:[obj.material]){materials.add(m);if(m.map)textures.add(m.map)}});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());while(group.children.length)group.remove(group.children[0])}
