function sandTexture(){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d'),r=R.rng(game.world.seed+2);ctx.fillStyle='#b0b297';ctx.fillRect(0,0,256,256);for(let i=0;i<18000;i++){let n=Math.floor(130+r()*80);ctx.fillStyle=`rgba(${n},${n},${Math.floor(n*.8)},.18)`;ctx.fillRect(r()*256,r()*256,1+r()*2,1)}for(let i=0;i<22;i++){ctx.beginPath();ctx.strokeStyle='#f3edca22';ctx.lineWidth=2;for(let x=0;x<256;x++){let y=i*13+Math.sin(x*.065+i)*3;x?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}const tex=new T.CanvasTexture(c);tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.repeat.set(12,12);tex.anisotropy=4;tex.colorSpace=T.SRGBColorSpace;return tex}
