 let geometry=new T.PlaneGeometry(span,span,100,100);geometry.rotateX(-Math.PI/2);let a=geometry.attributes.position;for(let i=0;i<a.count;i++)a.setY(i,w.floor(a.getX(i),a.getZ(i)));geometry.computeVertexNormals();
 const groundMat=mat(0xb5bba0,{map:sandTexture(),roughness:1});
 groundMat.onBeforeCompile=shader=>{shader.uniforms.uTime={value:0};shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vWorld;').replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvWorld = (modelMatrix * vec4(transformed, 1.0)).xyz;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vWorld;\nuniform float uTime;').replace('#include <dithering_fragment>','float ca = pow(abs(sin(vWorld.x*1.2 + sin(vWorld.z*.8 + uTime*.28)) * cos(vWorld.z*.9 + sin(vWorld.x*.7 - uTime*.22))), 9.0); gl_FragColor.rgb += vec3(.10,.20,.15)*ca;\n#include <dithering_fragment>');causticShader=shader};addMesh(geometry,groundMat);
 const rockTexture=makeRockTexture();for(const bed of w.rockBeds){const verts=[],indices=[],colors=[],segments=40,rings=8;for(let j=0;j<=rings;j++)for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2,b=1+.07*Math.sin(3*a+bed.phase)+.035*Math.cos(5*a-bed.phase),r=j/rings*bed.radius*b,x=bed.x+Math.cos(a)*r,z=bed.z+Math.sin(a)*r;verts.push(x,w.floor(x,z)+.025,z);colors.push(1,1,1,.68*T.MathUtils.smoothstep(1-j/rings,0,.4));if(j<rings&&i<segments){const n=j*(segments+1)+i;indices.push(n,n+1,n+segments+1,n+1,n+segments+2,n+segments+1)}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(verts,3));g.setIndex(indices);const uv=[];for(let i=0;i<verts.length;i+=3)uv.push(verts[i]*.65,verts[i+2]*.65);g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setAttribute('color',new T.Float32BufferAttribute(colors,4));g.computeVertexNormals();addMesh(g,mat(0xd0d1bb,{map:rockTexture,roughness:1,side:T.DoubleSide,vertexColors:true,transparent:true,depthWrite:false}))}
 const surface=addMesh(new T.PlaneGeometry(span,span,1,1),new T.MeshBasicMaterial({color:0x8bdace,transparent:true,opacity:.25,side:T.DoubleSide,depthWrite:false}));surface.rotation.x=Math.PI/2;surface.position.y=.2;
 for(let i=0;i<8;i++){let shaft=addMesh(new T.CylinderGeometry(.6,4+r()*4,35,18,1,true),new T.MeshBasicMaterial({color:0xa9fbeb,transparent:true,opacity:.025,side:T.DoubleSide,depthWrite:false,blending:T.AdditiveBlending}));shaft.position.set((r()-.5)*w.half*1.5,-12,(r()-.5)*w.half*1.5);shaft.rotation.z=-.25;shaft.rotation.x=.15}
 for(const rock of w.rocks){let m=addMesh(new T.DodecahedronGeometry(rock.r,1),mat(0x728a7c,{flatShading:true}));m.position.copy(rock);m.scale.y=.75;m.rotation.set(r(),r()*6.28,r());let moss=addMesh(new T.DodecahedronGeometry(rock.r*.7,0),mat(0x507c6e,{flatShading:true}));moss.position.set(rock.x,rock.y+rock.r*.4,rock.z);moss.scale.set(1,.4,1);moss.rotation.y=r()*6.28}
 // Colorful reef-inspired habitat, now rendered as freshwater ribbon-grass beds.
