 for(const c of w.corals){const g=V.buildCoral(r);g.position.set(c.x,c.y,c.z);g.scale.set(c.r,c.height,c.r);worldGroup.add(g);registerWildlife({group:g,center:{x:c.x,y:c.y+c.height*.5,z:c.z},kind:'coral',stationary:true})}
 // Small individual mussels form loose colonies, with scattered strays and nearby health bars.
 const shellTex=makeShellTexture(),shellGeometry=makeShellGeometry('quagga'),zebraGeometry=makeShellGeometry('zebra'),shellMaterial=mat(0xd0c39d,{map:shellTex,roughness:.6}),zebraMaterial=shellMaterial;
 const unknownMaterial=new T.SpriteMaterial({color:0xc7d1c8,depthWrite:false}),zebraBarMaterial=new T.SpriteMaterial({color:0x91b9ce,depthWrite:false}),idMaterial=new T.SpriteMaterial({color:0xc3a8f3,depthWrite:false});
 const blankLabel=new T.SpriteMaterial({transparent:true,opacity:0,depthWrite:false});
 const backMaterial=new T.SpriteMaterial({color:0x08252c,transparent:true,opacity:.95,depthWrite:false}),healthMaterials=[new T.SpriteMaterial({color:0xa3f0bd,depthWrite:false}),new T.SpriteMaterial({color:0xffcd78,depthWrite:false}),new T.SpriteMaterial({color:0xff7f78,depthWrite:false})];
 musselRenderData={shellGeometry,zebraGeometry,shellMaterial,zebraMaterial,blankLabel,backMaterial,healthMaterials,unknownMaterial,zebraBarMaterial,idMaterial};for(const m of w.mussels)spawnMusselMesh(m);
 footprint=new T.LineLoop(new T.BufferGeometry().setAttribute('position',new T.BufferAttribute(new Float32Array(80*3),3)),new T.LineBasicMaterial({color:R.TOOLS[game.selected].color,transparent:true,opacity:.65}));worldGroup.add(footprint);samplePreviewMesh=addMesh(new T.SphereGeometry(R.TOOLS.edna.radius,24,12),new T.MeshBasicMaterial({color:0xc7b7ff,transparent:true,opacity:.06,wireframe:true,depthWrite:false}));samplePreviewMesh.visible=false;
 // Native fish share the articulated perch rig, with distinct species silhouettes.
 for(let schoolId=0;schoolId<7;schoolId++){let x,z;if(schoolId===0){const f={x:-Math.sin(game.yaw),z:-Math.cos(game.yaw)},right={x:Math.cos(game.yaw),z:-Math.sin(game.yaw)};x=game.pos.x+f.x*6+right.x*6;z=game.pos.z+f.z*6+right.z*6}else{const a=r()*Math.PI*2,radius=(.15+r()*.3)*w.half;x=Math.cos(a)*radius;z=Math.sin(a)*radius}const center={x,y:Math.min(-1.5,w.floor(x,z)+3),z},school=V.createSchool(center,r);fishSchools.push(school);school.species=['perch','bluegill','trout','pike','perch','bluegill','trout'][schoolId];for(let i=0;i<10;i++)makeFish(school.center,r,schoolId*10+i,school)}
 let pp=new Float32Array(2100);for(let i=0;i<pp.length;i+=3){pp[i]=(r()-.5)*w.half*2.2;pp[i+1]=-r()*27;pp[i+2]=(r()-.5)*w.half*2.2}let pg=new T.BufferGeometry();pg.setAttribute('position',new T.BufferAttribute(pp,3));particles=new T.Points(pg,new T.PointsMaterial({color:0xd0fff5,size:.065,transparent:true,opacity:.4,depthWrite:false}));worldGroup.add(particles);
