function startDive(){game.start();narrator.start();$('welcome').classList.add('hidden');$('pauseOverlay').classList.add('hidden');keys.clear();lastTime=performance.now();canvas.focus({preventScroll:true});toast(`Remove ${game.requiredMussels} of ${game.world.quaggaCount} quaggas (80%) and sample 25% of the lake water volume. Use eDNA to investigate the unseen quagga edge.`);updateHUD()}
function pause(){if(game.state==='running'){game.pause();keys.clear();$('pauseOverlay').classList.remove('hidden')}else if(game.state==='paused'&&!$('guide').open){game.start();$('pauseOverlay').classList.add('hidden');lastTime=performance.now();canvas.focus({preventScroll:true})}updateHUD()}
function retry(){if(tutorial){startTutorial();return}const level=game.level;game.loadLevel(level);buildWorld();$('resultOverlay').classList.add('hidden');$('pauseOverlay').classList.add('hidden');game.start();narrator.start();keys.clear();lastTime=performance.now();canvas.focus({preventScroll:true});updateHUD()}
function jumpToLevel(level){
 if(!Number.isInteger(level)||level<1||level>100)return;
 if(tutorial){game.totalCleared=tutorial.savedCleared;game.totalSpent=tutorial.savedSpent}tutorial=null;$('tutorialPanel').classList.add('hidden');$('tutorialPointer').classList.add('hidden');
 keys.clear();mouse=null;impactUntil=0;penaltyUntil=0;game.loadLevel(level);buildWorld();
 for(const id of ['welcome','pauseOverlay','resultOverlay'])$(id).classList.add('hidden');
 document.querySelectorAll('[data-level-jump] input').forEach(input=>input.value=String(level));
 game.start();narrator.start();lastTime=performance.now();canvas.focus({preventScroll:true});updateHUD();
 toast(`Level ${level} · remove ${game.requiredMussels} of ${game.world.quaggaCount} quaggas and sample 25% of the water.`);
}
