 {targets:[['[data-tool=hydro]','Hydro blaster'],['[data-tool=scraper]','Scraper'],['[data-tool=chemical]','Chemical spray'],['#ecosystemPanel','Ecosystem health']],title:'Try a removal tool',text:'Aim at quaggas within tool range, keeping your distance from zebras, and press H for hydro or X for the scraper. C sprays chemicals over a wider area. All three can kill fish: protect wildlife! Each normally costs money and battery.',keys:'H HYDRO · X SCRAPER · C CHEMICAL',done:t=>t.usedTool},
 {targets:[['[data-tool=edna]','eDNA sample tool'],['#ednaReq','Water coverage goal']],title:'Collect an eDNA sample',text:'Press N to sample for mussel DNA. Our project uses eDNA to look for early warning signs of baby mussels (veligers) spreading through the water. Sample near and beyond the known mussel area, at different depths. Cover at least 25% of the water; overlapping samples count only once.',keys:'N · SAMPLE WATER',done:()=>game.scans>0},
 {targets:[['#batteryPanel','Battery level'],['#budget','Money remaining'],['#timer','Time remaining']],title:'Watch your battery and resources',text:'Your battery is shown in the highlighted panel. Movement and tools use power in a real mission. The money and timer displays show your remaining budget and time. Click a label below to locate each display. Practice keeps these resources full.',keys:'FIND YOUR BATTERY · THEN NEXT TIP',done:()=>false},
 {targets:[['#radar','Sonar / charging station'],['#batteryPanel','Battery and charging status'],['.fouling-panel','Motor fouling']],title:'Find the surface station',text:'Lightning markers on sonar show surface charging stations. Levels 1–5 have one station; another is added every five levels. Rise with E to within 1.8 m of the surface, and stay within 3 m of the buoy. It recharges your battery and cleans motor fouling.',keys:'E TO RISE · ⚡ ON SONAR',done:()=>game.atCharger()},
 {targets:[['.mission-progress','Level requirements'],['#batteryPanel','Battery level'],['#hullStatus','Hull health'],['#scoreValue','Mission score'],['#timer','Time remaining'],['#budget','Money remaining']],title:'Ready for your first mission',text:'Remove the required percentage of quaggas and sample 25% of the water. Watch time, money, hull health, and battery. Avoid rocks and lingering near zebras. Mussels reproduce if left alone. Click the labels below to find each display. Your mission starts fresh when you finish.',keys:'YOU ARE READY',done:()=>false}
